import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { addressSchema, type Address } from "./address.js";

/**
 * Defines the fields that are included in the request body of a request to the `CreateCustomerCard`
 * endpoint.
 */
export type CreateCustomerCardRequest = {
  /**
   * A card nonce representing the credit card to link to the customer.
   *
   * Card nonces are generated by the Square payment form when customers enter their card
   * information. For more information, see [Walkthrough: Integrate Square Payments in a
   * Website](https://developer.squareup.com/docs/web-payments/take-card-payment).
   *
   * __NOTE:__ Card nonces generated by digital wallets (such as Apple Pay) cannot be used to create
   * a customer card.
   */
  cardNonce: string;
  /**
   * Represents a postal address in a country. For more information, see [Working with
   * Addresses](https://developer.squareup.com/docs/build-basics/working-with-addresses).
   */
  billingAddress?: Address;
  /** The full name printed on the credit card. */
  cardholderName?: string;
  /**
   * An identifying token generated by
   * [Payments.verifyBuyer()](https://developer.squareup.com/reference/sdks/web/payments/objects/Payments#Payments.verifyBuyer).
   * Verification tokens encapsulate customer device information and 3-D Secure challenge results to
   * indicate that Square has verified the buyer identity.
   */
  verificationToken?: string;
};

export const createCustomerCardRequestSchema: Schema<CreateCustomerCardRequest> =
  s.object<CreateCustomerCardRequest>({
    cardNonce: s.string(),
    billingAddress: s.optional(s.lazy(() => addressSchema)),
    cardholderName: s.optional(s.string()),
    verificationToken: s.optional(s.string()),
    _keysMap: {
      cardNonce: "card_nonce",
      billingAddress: "billing_address",
      cardholderName: "cardholder_name",
      verificationToken: "verification_token",
    },
  });
